-- Čas: tags are shared by a team instead of being personal.
-- Generated by drizzle-kit, then reordered and given a backfill so it also runs on databases
-- that already have tags (the resulting schema is exactly what Drizzle expects):
-- - Training / Reading get fixed system tags (TS, Příprava na TS, Čtení, Esej);
-- - Practise / Projekt tags move to the owner's team, same names merge into one tag and
--   each owner keeps it visible (time_tag_selections);
-- - personal Training / Reading tags are dropped, automatic TS entries get the TS tag.
CREATE TABLE "time_tag_selections" (
	"profile_id" uuid NOT NULL,
	"tag_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "time_tag_selections_pkey" PRIMARY KEY("profile_id","tag_id")
);--> statement-breakpoint
ALTER TABLE "time_tag_selections" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE TABLE "time_tracking_preferences" (
	"profile_id" uuid PRIMARY KEY NOT NULL,
	"tags_reviewed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);--> statement-breakpoint
ALTER TABLE "time_tracking_preferences" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "time_tags" DROP CONSTRAINT "time_tags_profile_id_fkey";--> statement-breakpoint
ALTER TABLE "time_tags" DROP CONSTRAINT "time_tags_created_by_profile_id_fkey";--> statement-breakpoint
ALTER TABLE "time_tags" DROP CONSTRAINT "time_tags_updated_by_profile_id_fkey";--> statement-breakpoint
DROP INDEX "time_tags_profile_direction_name_key";--> statement-breakpoint
ALTER TABLE "time_tags" ALTER COLUMN "created_by_profile_id" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "time_tags" ALTER COLUMN "updated_by_profile_id" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "time_tags" ADD COLUMN "team_id" uuid;--> statement-breakpoint
ALTER TABLE "time_tags" ADD COLUMN "system_key" text;--> statement-breakpoint
ALTER TABLE "time_tag_selections" ADD CONSTRAINT "time_tag_selections_profile_id_fkey" FOREIGN KEY ("profile_id") REFERENCES "public"."profiles"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "time_tag_selections" ADD CONSTRAINT "time_tag_selections_tag_id_fkey" FOREIGN KEY ("tag_id") REFERENCES "public"."time_tags"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "time_tracking_preferences" ADD CONSTRAINT "time_tracking_preferences_profile_id_fkey" FOREIGN KEY ("profile_id") REFERENCES "public"."profiles"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "time_tag_selections_tag_idx" ON "time_tag_selections" USING btree ("tag_id" uuid_ops);--> statement-breakpoint
ALTER TABLE "time_tags" ADD CONSTRAINT "time_tags_team_id_fkey" FOREIGN KEY ("team_id") REFERENCES "public"."teams"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "time_tags" ADD CONSTRAINT "time_tags_created_by_profile_id_fkey" FOREIGN KEY ("created_by_profile_id") REFERENCES "public"."profiles"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "time_tags" ADD CONSTRAINT "time_tags_updated_by_profile_id_fkey" FOREIGN KEY ("updated_by_profile_id") REFERENCES "public"."profiles"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "time_tags_system_key_key" ON "time_tags" USING btree ("system_key" text_ops) WHERE (system_key IS NOT NULL);--> statement-breakpoint
CREATE INDEX "time_tags_team_idx" ON "time_tags" USING btree ("team_id" uuid_ops) WHERE (team_id IS NOT NULL);--> statement-breakpoint
-- Old per-person policies reference profile_id, so they go before the column does.
DROP POLICY "Users can create own time tags" ON "time_tags" CASCADE;--> statement-breakpoint
DROP POLICY "Users can update own time tags" ON "time_tags" CASCADE;--> statement-breakpoint
DROP POLICY "Users can delete own time tags" ON "time_tags" CASCADE;--> statement-breakpoint
ALTER POLICY "Team, coaches and admins can view time tags" ON "time_tags" TO authenticated USING ((team_id IS NULL OR is_coach_or_admin() OR team_id = (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL)));--> statement-breakpoint
ALTER TABLE "time_tags" ALTER COLUMN "profile_id" DROP NOT NULL;--> statement-breakpoint
-- ── Backfill: personal tags → team tags + fixed system tags ──────────────────────
-- Fixed tags of Training and Reading (shared by everyone, cannot be changed or hidden).
INSERT INTO "time_tags" ("system_key", "direction", "name") VALUES
	('training_session', 'training', 'TS'),
	('training_session_prep', 'training', 'Příprava na TS'),
	('reading', 'reading', 'Čtení'),
	('essay', 'reading', 'Esej');--> statement-breakpoint
-- Practise / Projekt tags move to their owner's team.
UPDATE "time_tags" t SET "team_id" = p."team_id"
FROM "profiles" p
WHERE p."id" = t."profile_id" AND t."direction" IN ('practise', 'project');--> statement-breakpoint
-- Same name (case-insensitive) in one team and direction = one tag; the oldest survives.
CREATE TEMP TABLE "time_tag_merge" ON COMMIT DROP AS
SELECT "id", first_value("id") OVER (
	PARTITION BY "team_id", "direction", lower(btrim("name"))
	ORDER BY "created_at", "id"
) AS "canonical_id"
FROM "time_tags"
WHERE "team_id" IS NOT NULL;--> statement-breakpoint
-- Everyone keeps seeing the tags they had (as the merged team tag).
INSERT INTO "time_tag_selections" ("profile_id", "tag_id")
SELECT DISTINCT t."profile_id", m."canonical_id"
FROM "time_tags" t
JOIN "time_tag_merge" m ON m."id" = t."id"
ON CONFLICT DO NOTHING;--> statement-breakpoint
UPDATE "time_entries" e SET "tag_id" = m."canonical_id"
FROM "time_tag_merge" m
WHERE e."tag_id" = m."id" AND m."id" <> m."canonical_id";--> statement-breakpoint
DELETE FROM "time_tags" t USING "time_tag_merge" m
WHERE t."id" = m."id" AND m."id" <> m."canonical_id";--> statement-breakpoint
-- Personal Training / Reading tags and tags of people without a team are dropped
-- (their entries keep the time and title, tag_id becomes NULL via the FK).
DELETE FROM "time_tags" WHERE "system_key" IS NULL AND "team_id" IS NULL;--> statement-breakpoint
-- Automatic Training Session entries get the TS tag.
UPDATE "time_entries" SET "tag_id" = (SELECT "id" FROM "time_tags" WHERE "system_key" = 'training_session')
WHERE "source" = 'attendance' AND "direction" = 'training';--> statement-breakpoint
-- ── End of backfill ───────────────────────────────────────────────────────────────
CREATE UNIQUE INDEX "time_tags_team_direction_name_key" ON "time_tags" USING btree ("team_id" uuid_ops,"direction" enum_ops,lower(btrim("name")));--> statement-breakpoint
ALTER TABLE "time_tags" DROP COLUMN "profile_id";--> statement-breakpoint
ALTER TABLE "time_tags" ADD CONSTRAINT "time_tags_scope_check" CHECK ((
		("time_tags"."team_id" IS NULL AND "time_tags"."system_key" IS NOT NULL AND "time_tags"."direction" IN ('training', 'reading'))
		OR ("time_tags"."team_id" IS NOT NULL AND "time_tags"."system_key" IS NULL AND "time_tags"."direction" IN ('practise', 'project'))
	));--> statement-breakpoint
CREATE POLICY "Team members can create team time tags" ON "time_tags" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((team_id = (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL) AND created_by_profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Creators, coaches and admins can update team time tags" ON "time_tags" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((team_id IS NOT NULL AND (created_by_profile_id = current_profile_id() OR is_coach_or_admin()))) WITH CHECK ((team_id IS NOT NULL AND ((team_id = (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL) AND created_by_profile_id = current_profile_id()) OR is_coach_or_admin())));--> statement-breakpoint
CREATE POLICY "Creators, coaches and admins can delete team time tags" ON "time_tags" AS PERMISSIVE FOR DELETE TO "authenticated" USING ((team_id IS NOT NULL AND (created_by_profile_id = current_profile_id() OR is_coach_or_admin())));--> statement-breakpoint
CREATE POLICY "Users can view own time tag selections" ON "time_tag_selections" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Users can create own time tag selections" ON "time_tag_selections" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((profile_id = current_profile_id() AND tag_id IN (SELECT id FROM time_tags WHERE team_id = (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL))));--> statement-breakpoint
CREATE POLICY "Users can delete own time tag selections" ON "time_tag_selections" AS PERMISSIVE FOR DELETE TO "authenticated" USING ((profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Users can view own time tracking preferences" ON "time_tracking_preferences" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Users can insert own time tracking preferences" ON "time_tracking_preferences" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ((profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Users can update own time tracking preferences" ON "time_tracking_preferences" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ((profile_id = current_profile_id())) WITH CHECK ((profile_id = current_profile_id()));
